   <body>
     <a class="skip-link" href="#main">Skip to main content</a>
     <div id="root"></div>

     <script>
       const notificationChoices = [
         {
           id: "notifications-email",
           value: "email",
           label: "Email",
           note: "Receive updates in your inbox.",
         },
         {
           id: "notifications-sms",
           value: "sms",
           label: "SMS",
           note: "Get text alerts on your phone.",
         },
         {
           id: "notifications-push",
           value: "push",
           label: "Push Notifications",
           note: "See alerts directly in the app.",
         },
       ];

       function RadioOption(choice) {
         return `
           <label class="radio-option" for="${choice.id}">
             <input
               type="radio"
               id="${choice.id}"
               name="notificationPreference"
               value="${choice.value}"
               required
             />
             <span class="radio-copy">
               <span class="radio-label">${choice.label}</span>
               <span class="radio-note">${choice.note}</span>
             </span>
           </label>
         `;
       }

       function NotificationForm() {
         return `
           <main id="main" class="page">
             <header class="hero">
               <p class="eyebrow">Preferences</p>
               <h1>Notification settings</h1>
               <p class="lead">Choose one way you'd like to hear from us.</p>
             </header>

             <section class="panel" aria-labelledby="notification-title">
               <form id="notification-form" novalidate>
                 <div class="form-field">
                   <fieldset>
                     <legend id="notification-title">How do you prefer to receive notifications?</legend>
                     <p class="help-text" id="notification-help">Select a single answer before submitting the form.</p>
                     <div class="radio-group" aria-describedby="notification-help">
                       ${notificationChoices.map(RadioOption).join("")}
                     </div>
                   </fieldset>
                 </div>

                 <div class="actions">
                   <button type="submit">Submit</button>
                 </div>

                 <p class="status" id="form-status" aria-live="polite"></p>
               </form>
             </section>
           </main>
         `;
       }

       document.getElementById("root").innerHTML = NotificationForm();

       const form = document.getElementById("notification-form");
       const status = document.getElementById("form-status");
       const radios = Array.from(document.querySelectorAll('input[name="notificationPreference"]'));

       form.addEventListener("submit", function (event) {
         event.preventDefault();

         const selected = radios.find((radio) => radio.checked);

         if (!selected) {
           radios.forEach((radio) => {
             radio.setAttribute("aria-invalid", "true");
           });
           status.textContent = "Please choose Email, SMS, or Push Notifications before submitting.";
           radios[0].focus();
           return;
         }

         radios.forEach((radio) => {
           radio.removeAttribute("aria-invalid");
         });

         status.textContent = `You selected ${selected.closest("label").querySelector(".radio-label").textContent}.`;
       });
     </script>
   </body>
